// Build the memory-aid prompt.
//
// Edit the wording here on the canvas.
//
// The excerpts arrive already read from Postgres under the student's own session, so RLS
// has decided what is in here. This node must not fetch anything else.

const body = $input.first().json.body ?? $input.first().json;
const { chunks } = body;

if (!Array.isArray(chunks) || chunks.length === 0) {
  throw new Error('payload must include at least one chunk');
}

const RULES = `You are helping a final-year university student memorise the lists they will have to recite in their project defense.

You will be given numbered excerpts from the student's own project.

Find the ordered lists in the excerpts. Typical ones are research objectives, research questions, hypotheses, the scope, limitations, and the significance of the study. Build one memory aid for each list you find, up to four.

Absolute rules:
- Only use lists that are actually in the excerpts. Never invent an item, never reword an item into something the project did not say, and never add an item to round a list up.
- This project has already been approved by the student's supervisor. Never comment on the quality of the list, and never note that something is absent.
- If the excerpts contain no clear ordered list, return an empty array. That is a correct answer.

Each aid:
- items: the list, in the project's own order, each shortened to a few words the student can hold in their head. Keep the project's own terminology.
- aid: the hook. Either a short memorable phrase whose words start with the same letters as the items in order, or a single vivid sentence that chains them in order. Keep it short enough to say in one breath.
- explanation: one line showing how the aid maps to the items, so it is learnable rather than just asserted.
- title: what the list is, in plain words, such as Research objectives.

Write plainly. Do not use em dashes.

Return ONLY a JSON array, no prose before or after, no markdown fence:
[{"title":"...","items":["...","..."],"aid":"...","explanation":"...","sources":[1]}]`;

const excerpts = chunks
  .map((c, i) => {
    const where = c.chapter
      ? `Chapter ${c.chapter}${c.label ? ` - ${c.label}` : ''}`
      : (c.label || 'Unlabelled section');
    return `[${i + 1}] (${where})
${c.content}`;
  })
  .join('

---

');

const prompt = `${RULES}

Excerpts from the project:

${excerpts}`;

return [{ json: { prompt } }];

// Parse and sanitise the model's JSON.
//
// An empty array is a legitimate result here, not a failure: plenty of chapters contain no
// ordered list worth memorising, and inventing one would break the grounding rule.

const j = $input.first().json ?? {};
const raw = j.text ?? j.response ?? j.output ?? '';

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('the model returned nothing');
}

const fenced = raw.replace(/```(?:json)?/gi, '');
const start = fenced.indexOf('[');
const end = fenced.lastIndexOf(']');

if (start === -1 || end <= start) {
  return [{ json: { mnemonics: [] } }];
}

let parsed;
try {
  parsed = JSON.parse(fenced.slice(start, end + 1));
} catch (e) {
  throw new Error('the response was not valid JSON: ' + e.message);
}

if (!Array.isArray(parsed)) throw new Error('expected an array');

const mnemonics = [];
for (const m of parsed) {
  if (!m || typeof m.title !== 'string' || typeof m.aid !== 'string') continue;
  if (!Array.isArray(m.items)) continue;

  const items = m.items.map((i) => String(i ?? '').trim()).filter(Boolean).slice(0, 12);

  // A one-item list needs no memory aid, and the table requires at least one item.
  if (items.length < 2) continue;
  if (!m.title.trim() || !m.aid.trim()) continue;

  const sources = Array.isArray(m.sources)
    ? [...new Set(m.sources.map((n) => Number(n) - 1).filter((n) => Number.isInteger(n) && n >= 0))]
    : [];

  mnemonics.push({
    title: m.title.trim(),
    items,
    aid: m.aid.trim(),
    explanation: typeof m.explanation === 'string' ? m.explanation.trim() : null,
    sourceIndexes: sources,
  });
}

return [{ json: { mnemonics: mnemonics.slice(0, 4) } }];
